class Solution {
    public int houseOfCards(int n) {
        // each row with t triangles uses 3t-1 cards; rows have strictly decreasing t going up
        int[] dp = new int[n + 1];
        dp[0] = 1;
        for (int t = 1; 3 * t - 1 <= n; t++) {
            int c = 3 * t - 1;
            for (int s = n; s >= c; s--) dp[s] += dp[s - c];
        }
        return dp[n];
    }
}
